import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.ArrayList;
import java.util.List;

public class MerkleTree {

    private List<String> transactions;
    private List<String> merkleTree;

    public MerkleTree(List<String> transactions) {
        this.transactions = transactions;
        this.merkleTree = buildMerkleTree(transactions);
    }

    private String calculateHash(String data) {
        try {
            MessageDigest digest = MessageDigest.getInstance("SHA-256");

            byte[] hashBytes =
                    digest.digest(data.getBytes(StandardCharsets.UTF_8));

            StringBuilder hexString = new StringBuilder();

            for (byte hashByte : hashBytes) {
                String hex = Integer.toHexString(0xff & hashByte);

                if (hex.length() == 1) {
                    hexString.append('0');
                }

                hexString.append(hex);
            }

            return hexString.toString();

        } catch (NoSuchAlgorithmException e) {
            e.printStackTrace();
        }

        return null;
    }

    private List<String> buildMerkleTree(List<String> transactions) {

        List<String> merkleTree = new ArrayList<>(transactions);

        int levelOffset = 0;

        for (int levelSize = transactions.size();
             levelSize > 1;
             levelSize = (levelSize + 1) / 2) {

            for (int left = 0; left < levelSize; left += 2) {

                int right = Math.min(left + 1, levelSize - 1);

                String leftHash =
                        merkleTree.get(levelOffset + left);

                String rightHash =
                        merkleTree.get(levelOffset + right);

                String parentHash =
                        calculateHash(leftHash + rightHash);

                merkleTree.add(parentHash);
            }

            levelOffset += levelSize;
        }

        return merkleTree;
    }

    public List<String> getMerkleTree() {
        return merkleTree;
    }

    public static void main(String[] args) {

        List<String> transactions = new ArrayList<>();

        transactions.add("Transaction 1");
        transactions.add("Transaction 2");
        transactions.add("Transaction 3");
        transactions.add("Transaction 4");
        transactions.add("Transaction 5");

        System.out.println("Transactions:");

        for (String tx : transactions) {
            System.out.println(tx);
        }

        System.out.println("\nMerkle Tree Hashes:");

        MerkleTree tree = new MerkleTree(transactions);

        for (String hash : tree.getMerkleTree()) {
            System.out.println(hash);
        }
    }
}

import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.Date;

public class Block {

    private int index;
    private long timestamp;
    private String previousHash;
    private String hash;
    private String data;
    private int nonce;

    public Block(int index, String previousHash, String data) {
        this.index = index;
        this.timestamp = new Date().getTime();
        this.previousHash = previousHash;
        this.data = data;
        this.nonce = 0;
        this.hash = calculateHash();
    }

    public String calculateHash() {
        try {
            MessageDigest digest = MessageDigest.getInstance("SHA-256");
            String input = index + timestamp + previousHash + data + nonce;
            byte[] hashBytes = digest.digest(input.getBytes());
            StringBuilder hexString = new StringBuilder();

            for (byte hashByte : hashBytes) {
                String hex = Integer.toHexString(0xff & hashByte);
                if (hex.length() == 1) hexString.append('0');
                hexString.append(hex);
            }
            return hexString.toString();
        } catch (NoSuchAlgorithmException e) {
            e.printStackTrace();
        }
        return null;
    }

    public void mineBlock(int difficulty) {
        String target = new String(new char[difficulty]).replace('\0', '0');
        while (!hash.substring(0, difficulty).equals(target)) {
            nonce++;
            hash = calculateHash();
        }
        System.out.println("Block mined: " + hash);
    }

    public int getIndex() {
        return index;
    }

    public long getTimestamp() {
        return timestamp;
    }

    public String getPreviousHash() {
        return previousHash;
    }

    public String getHash() {
        return hash;
    }

    public String getData() {
        return data;
    }

    public static void main(String[] args) {
        Block b = new Block(
            1,
            "3a42c503953909637f78dd8c99b3b85ddde362415585afc11901bdefe8349102",
            "Available"
        );

        b.calculateHash();
        b.mineBlock(1);
        System.out.println("Index: " + b.getIndex());
        System.out.println("Timestamp: " + b.getTimestamp());
        System.out.println("Previous Hash: " + b.getPreviousHash());
        System.out.println("Hash: " + b.getHash());
        System.out.println("Data: " + b.getData());
    }
}

