        this.difficulty = difficulty;

        createGenesisBlock();
    }

    private void createGenesisBlock() {
        Block genesisBlock = new Block(0, "0", "Genesis Block");
        genesisBlock.mineBlock(difficulty);
        chain.add(genesisBlock);
    }

