class Transaction {
    String sender;
    String receiver;
    double amount;

    public Transaction(String sender, String receiver, double amount) {
        this.sender = sender;
        this.receiver = receiver;
        this.amount = amount;
    }

    @Override
    public String toString() {
        return sender + " -> " + receiver + " : $" + amount;
    }
}

class Peer {
    String name;
    List<Peer> connectedPeers;
    List<Transaction> transactionPool;

    public Peer(String name) {
        this.name = name;
        this.connectedPeers = new ArrayList<>();
        this.transactionPool = new ArrayList<>();
    }

    public void connect(Peer peer) {
        if (!connectedPeers.contains(peer)) {
            connectedPeers.add(peer);
            peer.connectedPeers.add(this);
            System.out.println(this.name + " connected to " + peer.name);
        }
    }

    public void createTransaction(String sender, String receiver, double amount) {
        Transaction tx = new Transaction(sender, receiver, amount);
        System.out.println("\n" + this.name + " created transaction: " + tx);

        // Add to own pool
        transactionPool.add(tx);

        // Broadcast to peers
        broadcastTransaction(tx);
    }

    private void broadcastTransaction(Transaction tx) {
        System.out.println("Broadcasting transaction from " + this.name + " to peers...");
        for (Peer peer : connectedPeers) {
            peer.receiveTransaction(tx);
        }
    }

    public void receiveTransaction(Transaction tx) {
        if (!transactionPool.contains(tx)) {
            transactionPool.add(tx);
            System.out.println(this.name + " received transaction: " + tx);
        }
    }

    public void showTransactions() {
        System.out.println(this.name + " Transaction Pool: " + transactionPool.size() + " transactions");
        for (Transaction tx : transactionPool) {
            System.out.println("  - " + tx);
        }
    }
}

