import java.nio.charset.StandardCharsets;
import java.security.*;
import java.util.Base64;

public class BlockchainDigitalSignature {
    public static String calculateHash(String data) throws Exception {
        MessageDigest digest = MessageDigest.getInstance("SHA-256");
        byte[] hash = digest.digest(data.getBytes(StandardCharsets.UTF_8));
        StringBuilder hexString = new StringBuilder();

        for (byte b : hash) {
            String hex = Integer.toHexString(0xff & b);
            if (hex.length() == 1) {
                hexString.append('0');
            }
            hexString.append(hex);
        }

        return hexString.toString();
    }

    public static KeyPair generateKeyPair() throws Exception {
        KeyPairGenerator keyPairGenerator = KeyPairGenerator.getInstance("EC");
        keyPairGenerator.initialize(256);
        return keyPairGenerator.generateKeyPair();
    }

    public static String generateSignature(String transaction, PrivateKey privateKey) throws Exception {
        Signature signature = Signature.getInstance("SHA256withECDSA");
        signature.initSign(privateKey);
        signature.update(transaction.getBytes(StandardCharsets.UTF_8));
        byte[] digitalSignature = signature.sign();
        return Base64.getEncoder().encodeToString(digitalSignature);
    }

    public static boolean verifySignature(String transaction, String digitalSignature, PublicKey publicKey) throws Exception {
        Signature signature = Signature.getInstance("SHA256withECDSA");
        signature.initVerify(publicKey);
        signature.update(transaction.getBytes(StandardCharsets.UTF_8));
        byte[] signatureBytes = Base64.getDecoder().decode(digitalSignature);
        return signature.verify(signatureBytes);
    }

    public static void main(String[] args) {
        try {
            System.out.println("======================================");
            System.out.println(" BLOCKCHAIN DIGITAL SIGNATURE DEMO");
            System.out.println("======================================");

            KeyPair keyPair = generateKeyPair();
            PrivateKey privateKey = keyPair.getPrivate();
            PublicKey publicKey = keyPair.getPublic();

            System.out.println("\n1. ECDSA Key Pair Generated");
            System.out.println("--------------------------------------");
            System.out.println("Private Key Generated: YES");
            System.out.println("Public Key Generated : YES");

            String sender = "Alice";
            String receiver = "Bob";
            double amount = 10.0;
            String transaction = "Sender: " + sender + ", Receiver: " + receiver + ", Amount: " + amount + " ETH";

            System.out.println("\n2. Blockchain Transaction");
            System.out.println("--------------------------------------");
            System.out.println(transaction);

            String transactionHash = calculateHash(transaction);

            System.out.println("\n3. Transaction Hash (SHA-256)");
            System.out.println("--------------------------------------");
            System.out.println(transactionHash);

            String digitalSignature = generateSignature(transaction, privateKey);

            System.out.println("\n4. Digital Signature");
            System.out.println("--------------------------------------");
            System.out.println(digitalSignature);

            boolean valid = verifySignature(transaction, digitalSignature, publicKey);

            System.out.println("\n5. Signature Verification");
            System.out.println("--------------------------------------");

            if (valid) {
                System.out.println("Digital Signature is VALID.");
            } else {
                System.out.println("Digital Signature is INVALID.");
            }

            String modifiedTransaction = "Sender: Alice, Receiver: Bob, Amount: 100.0 ETH";

            System.out.println("\n6. Modified Transaction");
            System.out.println("--------------------------------------");
            System.out.println(modifiedTransaction);

            boolean modifiedValid = verifySignature(modifiedTransaction, digitalSignature, publicKey);

            System.out.println("\n7. Verification After Modification");
            System.out.println("--------------------------------------");

            if (modifiedValid) {
                System.out.println("Digital Signature is VALID.");
            } else {
                System.out.println("Digital Signature is INVALID.");
                System.out.println("Transaction has been modified!");
            }
        } catch (Exception e) {
            System.out.println("Error: " + e.getMessage());
            e.printStackTrace();
        }
    }
}

import java.security.*;
import java.security.spec.ECGenParameterSpec;

public class CryptoWallet {
    private PrivateKey privateKey;
    private PublicKey publicKey;

    public CryptoWallet() {
        generateKeyPair();
    }

    public void generateKeyPair() {
        try {
            KeyPairGenerator keyGen = KeyPairGenerator.getInstance("EC");
            SecureRandom random = SecureRandom.getInstanceStrong();

            ECGenParameterSpec ecSpec =
                    new ECGenParameterSpec("secp256r1");

            keyGen.initialize(ecSpec, random);

            KeyPair keyPair = keyGen.generateKeyPair();

            privateKey = keyPair.getPrivate();
            publicKey = keyPair.getPublic();

        } catch (Exception e) {
            e.printStackTrace();
        }
    }

    public static void main(String[] args) {
        CryptoWallet wallet = new CryptoWallet();

        System.out.println("Private Key: " + wallet.privateKey);
        System.out.println("Public Key: " + wallet.publicKey);
    }
}

